using System.Collections.ObjectModel;
using System.ComponentModel;
using System.IO;
using System.Windows.Input;
using DrawVerify.Core.Authorization;
using DrawVerify.Core.Interfaces;
using DrawVerify.Core.Models;

namespace DrawVerify.App.ViewModels;

public sealed class ReportTemplateConfigurationViewModel : TaskScreenViewModel
{
    private readonly IReportTemplateService _service; private readonly ISessionAuthenticationService _session; private readonly RoleAuthorization _authorization; private readonly ICentralizedLogger? _logger; private readonly IReportTemplatePreviewService? _preview; private string _message = ""; private string _errors = ""; private ReportTemplate? _selected;
    public ObservableCollection<ReportTemplate> Templates { get; } = new(); public ObservableCollection<SectionEditor> Sections { get; } = new(); public ObservableCollection<ColumnEditor> DimensionsColumns { get; } = new(); public ObservableCollection<ColumnEditor> GdtColumns { get; } = new(); public ObservableCollection<RuleEditor> DimensionsRules { get; } = new(); public ObservableCollection<RuleEditor> GdtRules { get; } = new(); public ObservableCollection<StatisticEditor> Statistics { get; } = new();
    public ReportTemplate? SelectedTemplate { get => _selected; set { _selected = value; LoadEditors(); RaisePropertyChanged(nameof(SelectedTemplate)); RaisePropertyChanged(string.Empty); } }
    public bool CanEdit => _session.IsAuthenticated && _authorization.IsAllowed(_session.CurrentUser, RolePermission.ManageGlobalConfiguration);
    public string Message { get => _message; private set { _message = value; RaisePropertyChanged(nameof(Message)); } } public string ValidationErrors { get => _errors; private set { _errors = value; RaisePropertyChanged(nameof(ValidationErrors)); } }
    public string OrganizationName { get => SelectedTemplate?.Header.OrganizationName ?? ""; set => UpdateHeader(SelectedTemplate?.Header with { OrganizationName = value }); } public string OrganizationAddress { get => SelectedTemplate?.Header.OrganizationAddress ?? ""; set => UpdateHeader(SelectedTemplate?.Header with { OrganizationAddress = value }); } public string ReportTitleFormat { get => SelectedTemplate?.Header.ReportTitleFormat ?? ""; set => UpdateHeader(SelectedTemplate?.Header with { ReportTitleFormat = value }); } public string LogoAssetPath { get => SelectedTemplate?.Header.LogoAssetPath ?? ""; set => UpdateHeader(SelectedTemplate?.Header with { LogoAssetPath = value }); } public string LogoPosition { get => SelectedTemplate?.Header.LogoPosition ?? "Left"; set => UpdateHeader(SelectedTemplate?.Header with { LogoPosition = value }); } public string TextAlignment { get => SelectedTemplate?.Header.TextAlignment ?? "Left"; set => UpdateHeader(SelectedTemplate?.Header with { TextAlignment = value }); }
    public string FooterText { get => SelectedTemplate?.Footer.Text ?? ""; set => UpdateFooter(SelectedTemplate?.Footer with { Text = value }); } public string PageNumberFormat { get => SelectedTemplate?.Footer.PageNumberFormat ?? ""; set => UpdateFooter(SelectedTemplate?.Footer with { PageNumberFormat = value }); } public string TemplateVersionLabel { get => SelectedTemplate?.Footer.TemplateVersionLabel ?? ""; set => UpdateFooter(SelectedTemplate?.Footer with { TemplateVersionLabel = value }); } public string EffectiveDate { get => SelectedTemplate?.Footer.EffectiveDate?.ToString("yyyy-MM-dd") ?? ""; set { if (DateTimeOffset.TryParse(value, out var date)) UpdateFooter(SelectedTemplate?.Footer with { EffectiveDate = date }); else if (!string.IsNullOrWhiteSpace(value)) ValidationErrors = "Effective date must be a valid date."; } }
    public string SummaryLayout { get => SelectedTemplate?.Summary.Layout ?? "Table"; set { if (SelectedTemplate is not null) UpdateTemplate(SelectedTemplate with { Summary = SelectedTemplate.Summary with { Layout = value } }); } }
    public string HeadingFontFamily { get => SelectedTemplate?.Style.HeadingFontFamily ?? "Helvetica"; set => UpdateStyle(SelectedTemplate?.Style with { HeadingFontFamily = value }); } public string BodyFontFamily { get => SelectedTemplate?.Style.BodyFontFamily ?? "Helvetica"; set => UpdateStyle(SelectedTemplate?.Style with { BodyFontFamily = value }); } public string TableFontFamily { get => SelectedTemplate?.Style.TableFontFamily ?? "Helvetica"; set => UpdateStyle(SelectedTemplate?.Style with { TableFontFamily = value }); } public double HeadingFontSize { get => SelectedTemplate?.Style.HeadingFontSize ?? 14; set => UpdateStyle(SelectedTemplate?.Style with { HeadingFontSize = value }); } public double BodyFontSize { get => SelectedTemplate?.Style.BodyFontSize ?? 9; set => UpdateStyle(SelectedTemplate?.Style with { BodyFontSize = value }); } public double TableFontSize { get => SelectedTemplate?.Style.TableFontSize ?? 8; set => UpdateStyle(SelectedTemplate?.Style with { TableFontSize = value }); } public string HeaderColor { get => SelectedTemplate?.Style.HeaderColor ?? "#000000"; set => UpdateStyle(SelectedTemplate?.Style with { HeaderColor = value }); } public string BorderColor { get => SelectedTemplate?.Style.BorderColor ?? "#000000"; set => UpdateStyle(SelectedTemplate?.Style with { BorderColor = value }); } public string HighlightColor { get => SelectedTemplate?.Style.HighlightColor ?? "#FF0000"; set => UpdateStyle(SelectedTemplate?.Style with { HighlightColor = value }); } public double Margin { get => SelectedTemplate?.Style.Margin ?? 40; set => UpdateStyle(SelectedTemplate?.Style with { Margin = value }); } public string Orientation { get => SelectedTemplate?.Style.Orientation ?? "Portrait"; set => UpdateStyle(SelectedTemplate?.Style with { Orientation = value }); }
    public ICommand NewCommand { get; } public ICommand DuplicateCommand { get; } public ICommand SaveCommand { get; } public ICommand DefaultCommand { get; } public ICommand DeleteCommand { get; } public ICommand PreviewCommand { get; } public ICommand MoveSectionUpCommand { get; } public ICommand MoveSectionDownCommand { get; }
    public ReportTemplateConfigurationViewModel(IReportTemplateService service, ISessionAuthenticationService session, RoleAuthorization authorization, ICentralizedLogger? logger = null, IReportTemplatePreviewService? preview = null, IReportTemplateExchangeService? exchange = null) { _service = service; _session = session; _authorization = authorization; _logger = logger; _preview = preview; NewCommand = new Command(async _ => await CreateAsync(), _ => CanEdit); DuplicateCommand = new Command(async _ => await DuplicateAsync(), _ => CanEdit && SelectedTemplate is not null); SaveCommand = new Command(async _ => await SaveAsync(), _ => CanEdit && SelectedTemplate is not null); DefaultCommand = new Command(async _ => await SetDefaultAsync(), _ => CanEdit && SelectedTemplate is not null); DeleteCommand = new Command(async _ => await DeleteAsync(), _ => CanEdit && SelectedTemplate is not null); PreviewCommand = new Command(async _ => await PreviewAsync(), _ => CanEdit && SelectedTemplate is not null && _preview is not null); MoveSectionUpCommand = new Command(p => MoveSectionAsync(p, -1), _ => CanEdit); MoveSectionDownCommand = new Command(p => MoveSectionAsync(p, 1), _ => CanEdit); _ = LoadAsync(); }
    public void SelectLogo(string path)
    {
        if (!CanEdit || string.IsNullOrWhiteSpace(path)) return;
        try
        {
            var extension = Path.GetExtension(path).ToLowerInvariant();
            if (extension is not ".png" and not ".jpg" and not ".jpeg" and not ".bmp") throw new InvalidOperationException("Report template logos must be PNG, JPEG, or BMP images.");
            if (!File.Exists(path)) throw new FileNotFoundException("The selected report template logo was not found.");
            if (new FileInfo(path).Length > 5 * 1024 * 1024) throw new InvalidOperationException("The selected report template logo exceeds the 5 MB limit.");
            var directory = Path.Combine(AppContext.BaseDirectory, "report-template-branding"); Directory.CreateDirectory(directory);
            var fileName = $"{Guid.NewGuid():N}{extension}"; File.Copy(path, Path.Combine(directory, fileName), true);
            LogoAssetPath = $"report-template-branding/{fileName}"; Message = "Logo copied to managed branding storage.";
        }
        catch (Exception ex) { Handle(ex, "select logo"); }
    }
    private void UpdateHeader(ReportTemplateHeader? value) { if (value is not null && SelectedTemplate is not null) UpdateTemplate(SelectedTemplate with { Header = value }); } private void UpdateFooter(ReportTemplateFooter? value) { if (value is not null && SelectedTemplate is not null) UpdateTemplate(SelectedTemplate with { Footer = value }); } private void UpdateStyle(ReportTemplateStyle? value) { if (value is not null && SelectedTemplate is not null) UpdateTemplate(SelectedTemplate with { Style = value }); } private void UpdateTemplate(ReportTemplate value) { _selected = value; IsDirty = true; RaisePropertyChanged(nameof(SelectedTemplate)); RaisePropertyChanged(string.Empty); }
    private void LoadEditors() { Sections.Clear(); DimensionsColumns.Clear(); GdtColumns.Clear(); DimensionsRules.Clear(); GdtRules.Clear(); Statistics.Clear(); if (SelectedTemplate is null) return; foreach (var x in SelectedTemplate.Sections.OrderBy(x => x.Ordinal)) Sections.Add(new SectionEditor(x, UpdateSection)); foreach (var x in SelectedTemplate.Tables.FirstOrDefault(x => x.Key == "Dimensions")?.Columns ?? []) DimensionsColumns.Add(new ColumnEditor(x, y => UpdateTable("Dimensions", y))); foreach (var x in SelectedTemplate.Tables.FirstOrDefault(x => x.Key == "Gdt")?.Columns ?? []) GdtColumns.Add(new ColumnEditor(x, y => UpdateTable("Gdt", y))); foreach (var x in SelectedTemplate.Tables.FirstOrDefault(x => x.Key == "Dimensions")?.ConditionalRules ?? []) DimensionsRules.Add(new RuleEditor(x, y => UpdateRule("Dimensions", y))); foreach (var x in SelectedTemplate.Tables.FirstOrDefault(x => x.Key == "Gdt")?.ConditionalRules ?? []) GdtRules.Add(new RuleEditor(x, y => UpdateRule("Gdt", y))); foreach (var x in SelectedTemplate.Summary.Statistics.OrderBy(x => x.Ordinal)) Statistics.Add(new StatisticEditor(x, UpdateStatistic)); }
    private void UpdateSection(ReportTemplateSection section) { if (SelectedTemplate is not null) UpdateTemplate(SelectedTemplate with { Sections = Sections.Select(x => x.Value).ToArray() }); } private void UpdateTable(string key, ReportTemplateColumn column) { if (SelectedTemplate is null) return; var tables = SelectedTemplate.Tables.Select(t => t.Key == key ? t with { Columns = (key == "Dimensions" ? DimensionsColumns : GdtColumns).Select(x => x.Value).ToArray() } : t).ToArray(); UpdateTemplate(SelectedTemplate with { Tables = tables }); } private void UpdateRule(string key, ReportTemplateConditionalRule rule) { if (SelectedTemplate is null) return; var tables = SelectedTemplate.Tables.Select(t => t.Key == key ? t with { ConditionalRules = (key == "Dimensions" ? DimensionsRules : GdtRules).Select(x => x.Value).ToArray() } : t).ToArray(); UpdateTemplate(SelectedTemplate with { Tables = tables }); } private void UpdateStatistic(ReportTemplateStatistic statistic) { if (SelectedTemplate is not null) UpdateTemplate(SelectedTemplate with { Summary = SelectedTemplate.Summary with { Statistics = Statistics.Select(x => x.Value).ToArray() } }); }
    private Task MoveSectionAsync(object? parameter, int delta) { if (parameter is not SectionEditor item) return Task.CompletedTask; var index = Sections.IndexOf(item); var target = index + delta; if (target < 0 || target >= Sections.Count) return Task.CompletedTask; Sections.Move(index, target); for (var i = 0; i < Sections.Count; i++) Sections[i].Ordinal = i; UpdateSection(item.Value); return Task.CompletedTask; }
    private async Task LoadAsync() { try { Templates.Clear(); foreach (var template in await _service.ListAsync()) Templates.Add(template); SelectedTemplate = Templates.FirstOrDefault(); } catch (Exception ex) { Handle(ex, "load"); } } private async Task CreateAsync() { try { var item = await _service.CreateAsync("New report template", _session.CurrentUser!.UserId); Templates.Add(item); SelectedTemplate = item; Message = "Template created."; } catch (Exception ex) { Handle(ex, "create"); } } private async Task DuplicateAsync() { try { var item = await _service.DuplicateAsync(SelectedTemplate!.Id, SelectedTemplate.Name + " copy", _session.CurrentUser!.UserId); Templates.Add(item); SelectedTemplate = item; Message = "Template duplicated."; } catch (Exception ex) { Handle(ex, "duplicate"); } } private async Task SaveAsync() { try { SelectedTemplate = await _service.SaveAsync(SelectedTemplate!, SelectedTemplate!.Version, _session.CurrentUser!.UserId); IsDirty = false; Message = "Template saved."; } catch (Exception ex) { Handle(ex, "save"); } } private async Task SetDefaultAsync() { try { await _service.SetDefaultAsync(SelectedTemplate!.Id, _session.CurrentUser!.UserId); await LoadAsync(); Message = "Organization default selected."; } catch (Exception ex) { Handle(ex, "set default"); } } private async Task DeleteAsync() { try { await _service.DeleteAsync(SelectedTemplate!.Id, SelectedTemplate.Version, _session.CurrentUser!.UserId); await LoadAsync(); Message = "Template deleted."; } catch (Exception ex) { Handle(ex, "delete"); } } private async Task PreviewAsync() { try { if (!CanEdit || _preview is null || SelectedTemplate is null) throw new UnauthorizedAccessException("Only an authenticated Admin can preview report templates."); await _preview.PreviewAsync(SelectedTemplate); Message = "Preview generated."; } catch (Exception ex) { Handle(ex, "preview"); } }
    private void Handle(Exception ex, string operation) { if (ex is not UnauthorizedAccessException) _logger?.Log(ex, $"Report template UI {operation}", "Report template operation failed."); Message = ex is UnauthorizedAccessException ? "Report template access denied." : $"Unable to {operation} report template."; ValidationErrors = ex.Message; }
    public sealed class SectionEditor : Notify { private ReportTemplateSection _value; private readonly Action<ReportTemplateSection> _changed; public SectionEditor(ReportTemplateSection value, Action<ReportTemplateSection> changed) { _value = value; _changed = changed; } public ReportTemplateSection Value => _value; public bool Enabled { get => _value.Enabled; set => Set(_value with { Enabled = value }); } public int Ordinal { get => _value.Ordinal; set => Set(_value with { Ordinal = value }); } public string Title { get => _value.Title; set => Set(_value with { Title = value }); } public string Description { get => _value.Description; set => Set(_value with { Description = value }); } private void Set(ReportTemplateSection value) { _value = value; Changed(); _changed(value); } }
    public sealed class ColumnEditor : Notify { private ReportTemplateColumn _value; private readonly Action<ReportTemplateColumn> _changed; public ColumnEditor(ReportTemplateColumn value, Action<ReportTemplateColumn> changed) { _value = value; _changed = changed; } public ReportTemplateColumn Value => _value; public string Field => _value.Field; public string Label { get => _value.Label; set => Set(_value with { Label = value }); } public int Precision { get => _value.Precision; set => Set(_value with { Precision = value }); } public string Unit { get => _value.Unit ?? ""; set => Set(_value with { Unit = value }); } private void Set(ReportTemplateColumn value) { _value = value; Changed(); _changed(value); } }
    public sealed class RuleEditor : Notify { private ReportTemplateConditionalRule _value; private readonly Action<ReportTemplateConditionalRule> _changed; public RuleEditor(ReportTemplateConditionalRule value, Action<ReportTemplateConditionalRule> changed) { _value = value; _changed = changed; } public ReportTemplateConditionalRule Value => _value; public string Field { get => _value.Field; set => Set(_value with { Field = value }); } public string Operator { get => _value.Operator; set => Set(_value with { Operator = value }); } public string ValueText { get => _value.Value; set => Set(_value with { Value = value }); } public string Color { get => _value.Color; set => Set(_value with { Color = value }); } private void Set(ReportTemplateConditionalRule value) { _value = value; Changed(); _changed(value); } }
    public sealed class StatisticEditor : Notify { private ReportTemplateStatistic _value; private readonly Action<ReportTemplateStatistic> _changed; public StatisticEditor(ReportTemplateStatistic value, Action<ReportTemplateStatistic> changed) { _value = value; _changed = changed; } public ReportTemplateStatistic Value => _value; public string Key => _value.Key; public string Label { get => _value.Label; set => Set(_value with { Label = value }); } public string Format { get => _value.Format; set => Set(_value with { Format = value }); } public int Ordinal { get => _value.Ordinal; set => Set(_value with { Ordinal = value }); } private void Set(ReportTemplateStatistic value) { _value = value; Changed(); _changed(value); } }
    public abstract class Notify : INotifyPropertyChanged { public event PropertyChangedEventHandler? PropertyChanged; protected void Changed([System.Runtime.CompilerServices.CallerMemberName] string? name = null) => PropertyChanged?.Invoke(this, new(name)); }
    private sealed class Command(Func<object?, Task> execute, Predicate<object?> can) : ICommand { public event EventHandler? CanExecuteChanged; public bool CanExecute(object? parameter) => can(parameter); public async void Execute(object? parameter) => await execute(parameter); }
}
